// 输出中文诊断日志，日志能力缺失时保持规则可运行。
function yuluLog(api, message) {
    try {
        if (api) {
            api.log(String(message));
        }
    } catch (error) {
        return;
    }
}

// 把字符串或对象统一解析为 JSON 数据并补充中文阶段错误。
function yuluParseJson(value, stage) {
    var text;
    if (value === null || typeof value === "undefined") {
        throw new Error(stage + "响应为空");
    }
    if (typeof value === "object") {
        // Rhino 会把 java.lang.String 暴露为对象，需先转成原生文本再解析。
        if (typeof value.charAt !== "function" || typeof value.substring !== "function") {
            return value;
        }
    }
    text = String(value);
    try {
        return JSON.parse(text);
    } catch (error) {
        throw new Error(stage + "响应 JSON 解析失败：" + error.message);
    }
}

// 复制普通对象，避免字段标准化时修改原始接口数据。
function yuluCopyObject(value) {
    var output = {};
    var key;
    if (!value || typeof value !== "object") {
        return output;
    }
    for (key in value) {
        if (Object.prototype.hasOwnProperty.call(value, key)) {
            output[key] = value[key];
        }
    }
    return output;
}

// 从多个候选字段中取得第一个非空值。
function yuluFirstValue(value, names, fallback) {
    var index;
    var current;
    for (index = 0; index < names.length; index += 1) {
        current = value ? value[names[index]] : null;
        if (current !== null && typeof current !== "undefined" && current !== "") {
            return current;
        }
    }
    return fallback;
}

// 识别 JavaScript 数组和 Rhino 暴露的带 length/数字索引类数组对象。
function yuluIsListLike(value) {
    var length;
    if (!value || typeof value === "string" || typeof value === "function") {
        return false;
    }
    if (Array.isArray(value)) {
        return true;
    }
    if (value.length === null || typeof value.length === "undefined") {
        return false;
    }
    length = Number(value.length);
    return isFinite(length) && length >= 0 && Math.floor(length) === length;
}

// 把脚本数组复制为 Java ArrayList，确保客户端 getElements 跨 Rhino 边界后保留条目。
function yuluToJavaList(values) {
    var output = new Packages.java.util.ArrayList();
    var index;
    for (index = 0; index < values.length; index += 1) {
        output.add(values[index]);
    }
    return output;
}

// 把标签数组或标量转换为 Legado 使用的分类字符串。
function yuluKindText(value) {
    var output = [];
    var index;
    var current;
    if (value === null || typeof value === "undefined") {
        return "";
    }
    if (yuluIsListLike(value)) {
        for (index = 0; index < value.length; index += 1) {
            current = value[index];
            if (current && typeof current === "object") {
                current = yuluFirstValue(current, ["tags_name", "tags_desc", "name", "title"], "");
            }
            if (current !== null && typeof current !== "undefined" && current !== "") {
                output.push(String(current));
            }
        }
        return output.join(", ");
    }
    if (typeof value === "object") {
        return String(yuluFirstValue(value, ["tags_name", "tags_desc", "name", "title"], ""));
    }
    return String(value);
}

// 把 Java 有符号字节转换为零到二百五十五的无符号值。
function yuluUnsignedByte(value) {
    return Number(value) & 255;
}

// 验证动态信封种子全为 ASCII 字节，并按 APK 字符串摘要路径解码。
function yuluAsciiSeedText(api, bytes) {
    var index;
    for (index = 0; index < bytes.length; index += 1) {
        if (yuluUnsignedByte(bytes[index]) > 127) {
            throw new Error("动态信封种子不是 ASCII");
        }
    }
    return api.bytesToStr(bytes, "US-ASCII");
}

// 用允许的 ByteArrayOutputStream 创建真实 Java ByteArray。
function yuluBytesFromRange(bytes, start, end) {
    var output = new Packages.java.io.ByteArrayOutputStream(end - start);
    var index;
    for (index = start; index < end; index += 1) {
        output.write(yuluUnsignedByte(bytes[index]));
    }
    return output.toByteArray();
}

// 把数值数组写入真实 Java ByteArray，避免使用被屏蔽的反射 API。
function yuluBytesFromArray(values) {
    var output = new Packages.java.io.ByteArrayOutputStream(values.length);
    var index;
    for (index = 0; index < values.length; index += 1) {
        output.write(yuluUnsignedByte(values[index]));
    }
    return output.toByteArray();
}

// 生成指定长度的零字节缓冲区，供 InputStream 的 read 调用写入。
function yuluZeroBytes(api, length) {
    var hex = "";
    var index;
    for (index = 0; index < length; index += 1) {
        hex += "00";
    }
    return api.hexDecodeToByteArray(hex);
}

// 把 ByteArray 或 InputStream 统一读取为 Java ByteArray。
function yuluReadAllBytes(api, input) {
    var output;
    var buffer;
    var count;
    var index;
    var one;
    if (input && typeof input.read !== "function" && typeof input.length === "number") {
        return input;
    }
    if (!input || typeof input.read !== "function") {
        throw new Error("图片数据既不是 ByteArray 也不是 InputStream");
    }
    output = new Packages.java.io.ByteArrayOutputStream(8192);
    buffer = yuluZeroBytes(api, 8192);
    while (true) {
        count = Number(input.read(buffer));
        if (count < 0) {
            break;
        }
        if (count === 0) {
            one = Number(input.read());
            if (one < 0) {
                break;
            }
            output.write(one & 255);
        } else {
            for (index = 0; index < count; index += 1) {
                output.write(yuluUnsignedByte(buffer[index]));
            }
        }
    }
    return output.toByteArray();
}

// 生成 yyyyMMdd 日期戳，支持测试传入固定日期。
function yuluDateStamp(fixedDate) {
    var now;
    var month;
    var day;
    if (fixedDate) {
        return String(fixedDate);
    }
    now = new Date();
    month = String(now.getMonth() + 1);
    day = String(now.getDate());
    if (month.length < 2) {
        month = "0" + month;
    }
    if (day.length < 2) {
        day = "0" + day;
    }
    return String(now.getFullYear()) + month + day;
}

// 按 APK 算法生成游客或登录态动态签名请求头。
function yuluHeaders(api, token, timestamp) {
    var time = timestamp;
    var tokenText = token ? String(token) : "";
    var signSource;
    if (time === null || typeof time === "undefined") {
        time = Math.floor(new Date().getTime() / 1000);
    }
    time = String(Math.floor(Number(time)));
    signSource = YULU_PACKAGE_NAME + tokenText + "1" + time + YULU_SIGN_SECRET;
    return {
        "Content-Type": "text/html; charset=UTF-8",
        "Connection": "close",
        "Accept": "*/*",
        "Access-Control-Allow-Origin": "*",
        "Access-Control-Allow-Headers": "X-Requested-With",
        "Vary": "Accept-Encoding",
        "User-Agent": "Mozilla/5.0_" + YULU_PACKAGE_NAME,
        "xf-appid": "11000001",
        "fc-session-id": "",
        "pt": "1",
        "version": YULU_VERSION,
        "channel": YULU_CHANNEL,
        "package": YULU_PACKAGE_NAME,
        "stamp": "",
        "time": time,
        "sign": api.md5Encode(signSource)
    };
}

// 解密搜索、详情、配置与漫画数据使用的动态 AES 信封。
function yuluDecryptEnvelope(api, envelope) {
    var value = yuluParseJson(envelope, "动态信封");
    var packed;
    var prefix;
    var suffix;
    var cipherBytes;
    var prefixText;
    var suffixText;
    var keyHex;
    var key;
    var md5Ascii;
    var ivValues = [];
    var iv;
    var index;
    var crypto;
    var plainBytes;
    if (Number(value.ver) !== 1) {
        throw new Error("不支持的动态信封版本：" + String(value.ver));
    }
    packed = api.base64DecodeToByteArray(String(value.content || ""));
    if (!packed || packed.length <= 32) {
        throw new Error("动态响应信封长度不足");
    }
    if ((packed.length - 32) % 16 !== 0) {
        throw new Error("动态响应密文块长度必须是 16 的倍数");
    }
    prefix = yuluBytesFromRange(packed, 0, 16);
    suffix = yuluBytesFromRange(packed, packed.length - 16, packed.length);
    cipherBytes = yuluBytesFromRange(packed, 16, packed.length - 16);
    prefixText = yuluAsciiSeedText(api, prefix);
    suffixText = yuluAsciiSeedText(api, suffix);
    keyHex = api.digestHex(prefixText, "SHA-256");
    key = api.hexDecodeToByteArray(String(keyHex));
    md5Ascii = api.strToBytes(api.md5Encode(suffixText), "US-ASCII");
    for (index = 0; index < 16; index += 1) {
        ivValues.push((~(yuluUnsignedByte(md5Ascii[index]) ^ yuluUnsignedByte(suffix[index]))) & 255);
    }
    iv = yuluBytesFromArray(ivValues);
    crypto = api.createSymmetricCrypto("AES/CBC/PKCS5Padding", key, iv);
    plainBytes = crypto.decrypt(cipherBytes);
    return api.bytesToStr(plainBytes);
}

// 解密小说目录标题和正文使用的固定 AES-128-CBC 密文。
function yuluDecryptFixed(api, cipherText) {
    var key;
    var iv;
    var crypto;
    var plainBytes;
    if (!cipherText) {
        return "";
    }
    key = api.strToBytes(YULU_FIXED_KEY);
    iv = api.strToBytes(YULU_FIXED_IV);
    crypto = api.createSymmetricCrypto("AES/CBC/PKCS5Padding", key, iv);
    plainBytes = crypto.decrypt(api.base64DecodeToByteArray(String(cipherText)));
    return api.bytesToStr(plainBytes);
}

// 解开接口 code/data 外层与动态信封，并返回其中 JSON 数据。
function yuluDecodeEnvelopeBody(api, body, stage) {
    var outer = yuluParseJson(body, stage);
    var envelope;
    var plain;
    if (outer.code !== null && typeof outer.code !== "undefined" && Number(outer.code) !== 1) {
        throw new Error(stage + "业务状态异常：" + String(outer.code));
    }
    envelope = outer.ver !== null && typeof outer.ver !== "undefined" ? outer : outer.data;
    if (typeof envelope === "string") {
        envelope = yuluParseJson(envelope, stage + "信封");
    }
    if (!envelope || typeof envelope.content === "undefined") {
        throw new Error(stage + "缺少动态加密信封");
    }
    plain = yuluDecryptEnvelope(api, envelope);
    return yuluParseJson(plain, stage + "解密");
}

// 构造编码查询参数 URL，保留原地址已有查询参数。
function yuluBuildUrl(api, baseUrl, params) {
    var output = String(baseUrl);
    var separator = output.indexOf("?") >= 0 ? "&" : "?";
    var key;
    var value;
    if (output.charAt(output.length - 1) === "?" || output.charAt(output.length - 1) === "&") {
        separator = "";
    }
    for (key in params) {
        if (Object.prototype.hasOwnProperty.call(params, key)) {
            value = params[key];
            if (value !== null && typeof value !== "undefined") {
                output += separator + api.encodeURI(String(key)) + "=" + api.encodeURI(String(value));
                separator = "&";
            }
        }
    }
    return output;
}

// 从 URL 查询参数中读取并解码指定字段。
function yuluQueryValue(url, name) {
    var text = String(url || "");
    var queryIndex = text.indexOf("?");
    var hashIndex;
    var pairs;
    var index;
    var parts;
    var key;
    var raw;
    if (queryIndex < 0) {
        return "";
    }
    text = text.substring(queryIndex + 1);
    hashIndex = text.indexOf("#");
    if (hashIndex >= 0) {
        text = text.substring(0, hashIndex);
    }
    pairs = text.split("&");
    for (index = 0; index < pairs.length; index += 1) {
        parts = pairs[index].split("=");
        try {
            key = decodeURIComponent(parts[0].replace(/\+/g, " "));
        } catch (error) {
            key = parts[0];
        }
        if (key === name) {
            raw = parts.length > 1 ? parts.slice(1).join("=") : "";
            try {
                return decodeURIComponent(raw.replace(/\+/g, " "));
            } catch (decodeError) {
                return raw;
            }
        }
    }
    return "";
}

// 从任意服务子域 URL 中提取当前根域名。
function yuluRootDomain(url) {
    var text = String(url || "");
    var match = /^[a-z]+:\/\/([^\/?#]+)/i.exec(text);
    var host;
    var parts;
    if (match) {
        host = match[1].split(":")[0].toLowerCase();
    } else {
        host = text.split("/")[0].split(":")[0].toLowerCase();
    }
    parts = host.split(".");
    if (parts.length >= 2) {
        return parts.slice(parts.length - 2).join(".");
    }
    return host;
}

// 把相对资源路径转换为指定服务子域的 HTTPS 地址。
function yuluServiceUrl(service, domain, path) {
    var value = String(path || "");
    if (/^https?:\/\//i.test(value)) {
        return value;
    }
    while (value.charAt(0) === "/") {
        value = value.substring(1);
    }
    return "https://" + service + "." + domain + "/" + value;
}

// 安全读取书源持久缓存，兼容缓存键尚未创建的情况。
function yuluSourceGet(source, key) {
    var value;
    if (!source || typeof source.get !== "function") {
        return "";
    }
    try {
        value = source.get(key);
        return value === null || typeof value === "undefined" ? "" : String(value);
    } catch (error) {
        return "";
    }
}

// 安全写入书源持久缓存，失败时保留主流程结果。
function yuluSourcePut(source, key, value) {
    if (!source || typeof source.put !== "function") {
        return;
    }
    try {
        source.put(key, String(value));
    } catch (error) {
        return;
    }
}

// 发起二次 GET，优先复用书源 ajax 网络栈和动态请求头，必要时回退 connect。
function yuluRequestBody(api, url, stage) {
    var requestUrl = String(url);
    var body;
    var ajaxError;
    var response;
    var status;
    var leading;
    yuluLog(api, stage + "请求：" + requestUrl);
    if (api) {
        try {
            body = api.ajax(requestUrl);
            leading = body === null || typeof body === "undefined" ? "" : String(body).replace(/^\s+/, "");
            if (leading.charAt(0) === "{" || leading.charAt(0) === "[") {
                yuluLog(api, stage + "请求完成：ajax");
                return body;
            }
            ajaxError = new Error(stage + " ajax 响应为空或不是 JSON");
            yuluLog(api, ajaxError.message + "，准备回退 connect");
        } catch (error) {
            ajaxError = error;
            yuluLog(api, stage + " ajax 请求异常：" + error.message + "，准备回退 connect");
        }
    }
    if (!api || typeof api.connect !== "function") {
        throw ajaxError || new Error(stage + "缺少可用请求方法");
    }
    response = api.connect(requestUrl, JSON.stringify(yuluHeaders(api, "")));
    if (!response || typeof response.body !== "function") {
        throw new Error(stage + "未返回可读取响应");
    }
    if (typeof response.code === "function") {
        status = Number(response.code());
        if (status >= 400) {
            throw new Error(stage + "请求失败，HTTP " + String(status));
        }
    }
    body = response.body();
    yuluLog(api, stage + "请求完成：connect" + (isFinite(status) ? "，HTTP " + String(status) : ""));
    return body;
}

// 按天发现并缓存服务根域，全部候选失败时回退旧主域。
function yuluDiscoverDomain(api, source, fixedDate) {
    var today = yuluDateStamp(fixedDate);
    var cachedDomain = yuluSourceGet(source, "yulu_domain").toLowerCase();
    var cachedDate = yuluSourceGet(source, "yulu_domain_date");
    var candidates = [];
    var seen = {};
    var index;
    var candidate;
    var url;
    var body;
    var config;
    var domain;
    if (cachedDomain && cachedDate === today) {
        return cachedDomain;
    }
    if (cachedDomain) {
        candidates.push(cachedDomain);
        seen[cachedDomain] = true;
    }
    for (index = 0; index < YULU_CONFIG_CANDIDATES.length; index += 1) {
        candidate = YULU_CONFIG_CANDIDATES[index];
        if (!seen[candidate]) {
            candidates.push(candidate);
            seen[candidate] = true;
        }
    }
    for (index = 0; index < candidates.length; index += 1) {
        candidate = candidates[index];
        url = "https://conf." + candidate + "/v4/android/" + YULU_PACKAGE_NAME + "/" + YULU_CHANNEL;
        url = yuluBuildUrl(api, url, { t: today });
        try {
            body = yuluRequestBody(api, url, "域名配置 " + candidate);
            config = yuluDecodeEnvelopeBody(api, body, "域名配置 " + candidate);
            domain = config && config.urls ? String(config.urls.domain || "").toLowerCase() : "";
            if (!/^(?:[a-z0-9-]+\.)+[a-z]{2,}$/.test(domain)) {
                throw new Error("配置下发根域格式无效");
            }
            yuluSourcePut(source, "yulu_domain", domain);
            yuluSourcePut(source, "yulu_domain_date", today);
            return domain;
        } catch (error) {
            yuluLog(api, "域名配置 " + candidate + " 失败：" + error.message);
        }
    }
    yuluLog(api, "全部域名配置失败，回退 wendulou.com");
    yuluSourcePut(source, "yulu_domain", "wendulou.com");
    return "wendulou.com";
}

// 清理失效动态域缓存，让下一次发现请求重新读取配置接口。
function yuluInvalidateDomain(api, source, failedDomain, stage) {
    var cachedDomain = yuluSourceGet(source, "yulu_domain");
    yuluSourcePut(source, "yulu_domain", "");
    yuluSourcePut(source, "yulu_domain_date", "");
    yuluLog(api, stage + "清理动态域缓存：" + String(cachedDomain || failedDomain || "空"));
}

// 清理旧缓存后重新发现根域，并记录前后域名供手机日志定位。
function yuluRefreshDomain(api, source, failedDomain, stage) {
    var refreshedDomain;
    yuluInvalidateDomain(api, source, failedDomain, stage);
    refreshedDomain = yuluDiscoverDomain(api, source);
    yuluLog(api, stage + "动态域重取：" + String(failedDomain || "空") + " -> " + refreshedDomain);
    return refreshedDomain;
}

// 发现当前根域并构造小说或漫画聚合搜索地址。
function yuluBuildSearchUrl(api, source, keyword, form, fixedDate) {
    var domain = yuluDiscoverDomain(api, source, fixedDate);
    return yuluBuildUrl(api, "https://s." + domain + "/v4/1/lists.api", {
        keyword: keyword,
        form: form
    });
}

// 把接口原始书籍字段标准化为 Legado 可直接读取的简单属性。
function yuluNormalizeBook(raw, domain, form, detailBaseUrl) {
    var output = yuluCopyObject(raw);
    var id = yuluFirstValue(raw, ["book_id", "id"], "");
    var numericId = Number(id);
    var actualForm = Number(form || yuluFirstValue(raw, ["form"], 1));
    var image = yuluFirstValue(raw, ["image", "cover", "cover_url"], "");
    var floor = isFinite(numericId) ? Math.floor(numericId / 1000) : 0;
    var tags = raw ? raw.tags : null;
    var kind = yuluKindText(tags);
    var ltype;
    var stype;
    output.book_id = id;
    output.name = String(yuluFirstValue(raw, ["name", "book_name", "title"], ""));
    output.author = String(yuluFirstValue(raw, ["author", "author_name", "writer"], ""));
    if (!kind) {
        ltype = String(yuluFirstValue(raw, ["ltype"], ""));
        stype = String(yuluFirstValue(raw, ["stype"], ""));
        if (ltype) {
            kind = ltype;
        }
        if (stype && stype !== ltype) {
            kind += (kind ? ", " : "") + stype;
        }
    }
    if (!kind) {
        kind = yuluKindText(yuluFirstValue(raw, ["kind", "category", "class_name"], ""));
    }
    output.kind = kind;
    output.word_count = yuluFirstValue(raw, ["word_count", "words_number", "words", "word", "chapter_count"], "");
    output.last_chapter = String(yuluFirstValue(raw, ["last_chapter", "last_chapter_name", "last_name", "latest_chapter"], ""));
    output.intro = String(yuluFirstValue(raw, ["intro", "remark", "description", "desc", "summary"], ""));
    output.cover_url = image ? yuluServiceUrl(actualForm === 3 ? "c-res" : "res", domain, image) : "";
    if (id !== "") {
        if (actualForm === 3) {
            output.detail_url = "https://book." + domain + "/comics/details/v4/" + floor + "/" + id + ".html";
        } else {
            output.detail_url = "https://d." + domain + "/book/details/v4/" + floor + "/" + id + ".html";
        }
    } else {
        output.detail_url = String(detailBaseUrl || "");
    }
    output.toc_url = String(yuluFirstValue(raw, ["toc_url"], ""));
    return output;
}

// 判断搜索项是否为带书籍编号的有效对象，过滤作者字符串建议和空项。
function yuluValidSearchBook(value) {
    var id;
    if (!value || typeof value !== "object" || yuluIsListLike(value)) {
        return false;
    }
    id = yuluFirstValue(value, ["book_id", "id"], "");
    return id !== "";
}

// 追加聚合搜索项并按 book_id 去重，兼容作者项内嵌 books 数组。
function yuluAppendSearchItems(output, seen, items, domain, form, baseUrl) {
    var index;
    var item;
    var nested;
    var nestedIndex;
    var normalized;
    var key;
    if (!yuluIsListLike(items)) {
        return;
    }
    for (index = 0; index < items.length; index += 1) {
        item = items[index];
        nested = item && yuluIsListLike(item.books) ? item.books : null;
        if (nested) {
            for (nestedIndex = 0; nestedIndex < nested.length; nestedIndex += 1) {
                if (yuluValidSearchBook(nested[nestedIndex])) {
                    normalized = yuluNormalizeBook(nested[nestedIndex], domain, form, baseUrl);
                    key = String(normalized.book_id);
                    if (!seen[key]) {
                        seen[key] = true;
                        output.push(normalized);
                    }
                }
            }
        } else if (yuluValidSearchBook(item)) {
            normalized = yuluNormalizeBook(item, domain, form, baseUrl);
            key = String(normalized.book_id);
            if (!seen[key]) {
                seen[key] = true;
                output.push(normalized);
            }
        }
    }
}

// 解密聚合搜索响应、合并书籍与作者结果并标准化字段。
function yuluSearchBooks(api, body, baseUrl, form) {
    var data = yuluDecodeEnvelopeBody(api, body, "聚合搜索");
    var domain = yuluRootDomain(baseUrl);
    var output = [];
    var seen = {};
    var bookLength;
    var authorLength;
    var retryBody;
    var retryError;
    var diagnosticBody;
    var diagnosticOuter;
    var diagnosticCode = "未知";
    var diagnosticText;
    var dataKeys = [];
    var dataKey;
    yuluAppendSearchItems(output, seen, data.book, domain, Number(form || 1), baseUrl);
    yuluAppendSearchItems(output, seen, data.author, domain, Number(form || 1), baseUrl);
    if (output.length === 0) {
        try {
            yuluLog(api, "聚合搜索首响应为空，按同一书名 URL 通过 ajax 重取：" + String(baseUrl));
            retryBody = api.ajax(String(baseUrl));
            data = yuluDecodeEnvelopeBody(api, retryBody, "聚合搜索重取");
            yuluAppendSearchItems(output, seen, data.book, domain, Number(form || 1), baseUrl);
            yuluAppendSearchItems(output, seen, data.author, domain, Number(form || 1), baseUrl);
        } catch (error) {
            retryError = error;
            yuluLog(api, "聚合搜索 ajax 重取失败：" + error.message);
        }
    }
    bookLength = data && data.book && typeof data.book.length !== "undefined" ? Number(data.book.length) : -1;
    authorLength = data && data.author && typeof data.author.length !== "undefined" ? Number(data.author.length) : -1;
    yuluLog(api, "聚合搜索解析完成：book类型=" + typeof (data && data.book) + "，book长度=" + String(bookLength) +
        "，author类型=" + typeof (data && data.author) + "，author长度=" + String(authorLength) +
        "，输出=" + String(output.length));
    if (output.length === 0) {
        // 手机端日志能力缺失时通过异常保留最小响应摘要，定位完成后删除该诊断分支。
        diagnosticBody = retryBody === null || typeof retryBody === "undefined" ? body : retryBody;
        try {
            diagnosticOuter = yuluParseJson(diagnosticBody, "聚合搜索诊断");
            if (diagnosticOuter.code !== null && typeof diagnosticOuter.code !== "undefined") {
                diagnosticCode = String(diagnosticOuter.code);
            }
        } catch (diagnosticError) {
            diagnosticCode = "解析失败：" + diagnosticError.message;
        }
        for (dataKey in data) {
            if (Object.prototype.hasOwnProperty.call(data, dataKey)) {
                dataKeys.push(String(dataKey));
            }
        }
        diagnosticText = String(diagnosticBody).replace(/\s+/g, " ").substring(0, 240);
        throw new Error("[YULU-SEARCH-DIAG] 聚合搜索结果为零：baseUrl=" + String(baseUrl) +
            "，form=" + String(form) + "，code=" + diagnosticCode + "，data键=" + dataKeys.join(",") +
            "，book长度=" + String(bookLength) + "，author长度=" + String(authorLength) +
            "，重取错误=" + (retryError ? retryError.message : "无") + "，响应前缀=" + diagnosticText);
    }
    return yuluToJavaList(output);
}

// 把可用率百分比转换为排序数值。
function yuluChooseNumber(value) {
    var number = parseFloat(String(value === null || typeof value === "undefined" ? "" : value).replace("%", ""));
    return isFinite(number) ? number : -1;
}

// 把数值或完整日期字符串解析为可比较时间，非法值统一回退为零。
function yuluUpdatedTime(value) {
    var text;
    var match;
    var year;
    var month;
    var day;
    var hour;
    var minute;
    var second;
    var time;
    var parsed;
    if (typeof value === "number") {
        return isFinite(value) ? value : 0;
    }
    text = String(value === null || typeof value === "undefined" ? "" : value).replace(/^\s+|\s+$/g, "");
    if (/^[+-]?\d+(?:\.\d+)?$/.test(text)) {
        time = Number(text);
        return isFinite(time) ? time : 0;
    }
    match = /^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})$/.exec(text);
    if (!match) {
        return 0;
    }
    year = Number(match[1]);
    month = Number(match[2]);
    day = Number(match[3]);
    hour = Number(match[4]);
    minute = Number(match[5]);
    second = Number(match[6]);
    time = Date.UTC(year, month - 1, day, hour, minute, second);
    parsed = new Date(time);
    if (parsed.getUTCFullYear() !== year || parsed.getUTCMonth() !== month - 1 ||
            parsed.getUTCDate() !== day || parsed.getUTCHours() !== hour ||
            parsed.getUTCMinutes() !== minute || parsed.getUTCSeconds() !== second) {
        return 0;
    }
    return time;
}

// 比较小说源的可用率与更新时间，均按降序排列。
function yuluCompareNovelSource(left, right) {
    var chooseDifference = yuluChooseNumber(right.choose) - yuluChooseNumber(left.choose);
    if (chooseDifference !== 0) {
        return chooseDifference;
    }
    return yuluUpdatedTime(right.updated_at) - yuluUpdatedTime(left.updated_at);
}

// 过滤空目录路径并按 choose 百分比和更新时间排序小说源。
function yuluSortNovelSources(sources) {
    var output = [];
    var index;
    if (!yuluIsListLike(sources)) {
        return output;
    }
    for (index = 0; index < sources.length; index += 1) {
        if (sources[index] && sources[index].site_path) {
            output.push(sources[index]);
        }
    }
    output.sort(yuluCompareNovelSource);
    return output;
}

// 把接口下发的站点正则数组整理为按 site_id 索引的缓存对象。
function yuluRegularMap(items) {
    var output = {};
    var index;
    var item;
    var siteId;
    if (!yuluIsListLike(items)) {
        return output;
    }
    for (index = 0; index < items.length; index += 1) {
        item = items[index] || {};
        siteId = String(yuluFirstValue(item, ["site_id", "siteId", "id"], ""));
        if (siteId) {
            output[siteId] = yuluIsListLike(item.regular) ? item.regular : [];
        }
    }
    return output;
}

// 获取并缓存 APK 下发的小说站点正文替换规则。
function yuluLoadRegulars(api, source, domain) {
    var cached = yuluSourceGet(source, "yulu_site_regulars");
    var body;
    var data;
    var mapped;
    if (cached) {
        try {
            mapped = yuluParseJson(cached, "站点正则缓存");
            if (mapped && typeof mapped === "object") {
                return mapped;
            }
        } catch (error) {
            yuluLog(api, "站点正则缓存损坏，将重新请求：" + error.message);
        }
    }
    body = yuluRequestBody(api, "https://conf." + domain + "/v4/source/site.html", "站点正则");
    data = yuluDecodeEnvelopeBody(api, body, "站点正则");
    mapped = yuluRegularMap(data);
    yuluSourcePut(source, "yulu_site_regulars", JSON.stringify(mapped));
    return mapped;
}

// 请求并解密指定根域的小说源列表。
function yuluLoadNovelSourceList(api, domain, id, floor) {
    var sourceUrl = "https://d." + domain + "/book/source/v4/" + String(floor) + "/" + String(id) + ".html";
    return yuluDecodeEnvelopeBody(api, yuluRequestBody(api, sourceUrl, "小说源"), "小说源");
}

// 合并小说详情、首选站点源和正文正则缓存，旧域失败时只重试一次。
function yuluNovelDetail(api, source, body, detailUrl) {
    var data = yuluDecodeEnvelopeBody(api, body, "小说详情");
    var domain = yuluRootDomain(detailUrl);
    var id = yuluFirstValue(data, ["book_id", "id"], "");
    var numericId = Number(id);
    var floor = isFinite(numericId) ? Math.floor(numericId / 1000) : 0;
    var normalized;
    var sources;
    var sorted;
    var selected;
    var siteId;
    try {
        sources = yuluLoadNovelSourceList(api, domain, id, floor);
        sorted = yuluSortNovelSources(sources);
        if (sorted.length === 0) {
            throw new Error("小说详情没有可用目录源");
        }
    } catch (error) {
        yuluLog(api, "小说源首次请求失败（可能为 HTTP/业务 403 或旧域失效）：" + error.message);
        domain = yuluRefreshDomain(api, source, domain, "小说源");
        sources = yuluLoadNovelSourceList(api, domain, id, floor);
        sorted = yuluSortNovelSources(sources);
    }
    if (sorted.length === 0) {
        throw new Error("小说详情没有可用目录源");
    }
    normalized = yuluNormalizeBook(data, domain, 1, detailUrl);
    selected = sorted[0];
    siteId = String(yuluFirstValue(selected, ["site_id", "siteId", "id"], ""));
    if (!siteId) {
        throw new Error("小说目录源缺少 site_id");
    }
    normalized.toc_url = yuluBuildUrl(api, yuluServiceUrl("catalog", domain, selected.site_path), {
        yulu_site_id: siteId
    });
    yuluLoadRegulars(api, source, domain);
    return normalized;
}

// 解开小说目录的普通 code/data 外层，必要时兼容动态信封。
function yuluNovelChapterData(api, body) {
    var outer = yuluParseJson(body, "小说目录");
    if (outer.code !== null && typeof outer.code !== "undefined" && Number(outer.code) !== 1) {
        throw new Error("小说目录业务状态异常：" + String(outer.code));
    }
    if (outer.ver !== null && typeof outer.ver !== "undefined") {
        return yuluParseJson(yuluDecryptEnvelope(api, outer), "小说目录解密");
    }
    if (outer.data && typeof outer.data.content !== "undefined" && typeof outer.data.ver !== "undefined") {
        return yuluParseJson(yuluDecryptEnvelope(api, outer.data), "小说目录解密");
    }
    return outer.data || [];
}

// 解密小说章节标题并把目录路径转换为保留 site_id 的正文地址。
function yuluNovelChapters(api, body, tocUrl) {
    var data = yuluNovelChapterData(api, body);
    var domain = yuluRootDomain(tocUrl);
    var siteId = yuluQueryValue(tocUrl, "yulu_site_id");
    var output = [];
    var index;
    var item;
    var chapterUrl;
    if (!yuluIsListLike(data)) {
        throw new Error("小说目录数据不是数组");
    }
    for (index = 0; index < data.length; index += 1) {
        item = data[index] || {};
        chapterUrl = yuluServiceUrl("chapter", domain, yuluFirstValue(item, ["path", "url"], ""));
        if (siteId) {
            chapterUrl = yuluBuildUrl(api, chapterUrl, { yulu_site_id: siteId });
        }
        output.push({
            title: yuluDecryptFixed(api, yuluFirstValue(item, ["name", "title"], "")),
            url: chapterUrl,
            updated_at: yuluFirstValue(item, ["updated_at", "time"], "")
        });
    }
    return output;
}

// 按站点配置顺序执行正文正则替换，单条非法规则只记录中文日志。
function yuluApplyRegulars(api, content, regulars) {
    var output = String(content === null || typeof content === "undefined" ? "" : content);
    var index;
    var item;
    var pattern;
    var replacement;
    if (!yuluIsListLike(regulars)) {
        return output;
    }
    for (index = 0; index < regulars.length; index += 1) {
        item = regulars[index] || {};
        pattern = yuluFirstValue(item, ["regular_key", "pattern", "key"], "");
        replacement = yuluFirstValue(item, ["regular_value", "replacement", "value"], "");
        if (pattern !== "") {
            try {
                output = output.replace(new RegExp(String(pattern), "g"), String(replacement));
            } catch (error) {
                yuluLog(api, "正文正则执行失败：" + error.message);
            }
        }
    }
    return output;
}

// 解密小说正文并按当前 URL 的 site_id 应用缓存正则。
function yuluNovelContent(api, source, body, contentUrl) {
    var outer = yuluParseJson(body, "小说正文");
    var data;
    var siteId = yuluQueryValue(contentUrl, "yulu_site_id");
    var cached;
    var mapped = {};
    var plain;
    if (outer.code !== null && typeof outer.code !== "undefined" && Number(outer.code) !== 1) {
        throw new Error("小说正文业务状态异常：" + String(outer.code));
    }
    data = outer.data || outer;
    plain = yuluDecryptFixed(api, yuluFirstValue(data, ["content", "text"], ""));
    cached = yuluSourceGet(source, "yulu_site_regulars");
    if (cached) {
        try {
            mapped = yuluParseJson(cached, "站点正则缓存");
        } catch (error) {
            yuluLog(api, "站点正则缓存读取失败：" + error.message);
        }
    }
    return yuluApplyRegulars(api, plain, mapped && mapped[siteId]);
}

// 按 APK 中 source_comic.json 顺序选择漫画源，并兼容仅含聚合路径的数据。
function yuluSelectComicSource(data) {
    var sources = data && yuluIsListLike(data.sources) ? data.sources : [];
    var priorityIndex;
    var sourceIndex;
    var item;
    var sourceId;
    var output;
    for (priorityIndex = 0; priorityIndex < YULU_COMIC_SOURCE_PRIORITY.length; priorityIndex += 1) {
        for (sourceIndex = 0; sourceIndex < sources.length; sourceIndex += 1) {
            item = sources[sourceIndex] || {};
            sourceId = String(yuluFirstValue(item, ["source_id", "sourceId", "id"], ""));
            if (sourceId === YULU_COMIC_SOURCE_PRIORITY[priorityIndex] && item.list_path) {
                output = yuluCopyObject(item);
                output.source_id = sourceId;
                return output;
            }
        }
    }
    if (data && data.list_path) {
        return { source_id: "aggregate", list_path: data.list_path };
    }
    throw new Error("漫画详情没有可用目录源");
}

// 优先从详情数据读取 book_id，缺失时再从详情 URL 的文件名提取。
function yuluBookIdFromDetail(data, detailUrl) {
    var id = yuluFirstValue(data, ["book_id", "id"], "");
    var match;
    if (id !== "") {
        return String(id);
    }
    match = /\/(\d+)\.html(?:[?#].*)?$/.exec(String(detailUrl || ""));
    return match ? match[1] : "";
}

// 标准化漫画详情；目录字段缺失时清理旧域并按 book_id 重取一次。
function yuluComicDetail(api, source, body, detailUrl) {
    var data = yuluDecodeEnvelopeBody(api, body, "漫画详情");
    var domain = yuluRootDomain(detailUrl);
    var normalized;
    var selected;
    var id;
    var numericId;
    var floor;
    var retryUrl;
    try {
        selected = yuluSelectComicSource(data);
    } catch (error) {
        id = yuluBookIdFromDetail(data, detailUrl);
        if (!id) {
            throw error;
        }
        yuluLog(api, "漫画详情缺少目录，准备清理动态域并重取 book_id=" + id + "：" + error.message);
        domain = yuluRefreshDomain(api, source, domain, "漫画详情");
        numericId = Number(id);
        floor = isFinite(numericId) ? Math.floor(numericId / 1000) : 0;
        retryUrl = "https://book." + domain + "/comics/details/v4/" + String(floor) + "/" + id + ".html";
        data = yuluDecodeEnvelopeBody(api, yuluRequestBody(api, retryUrl, "漫画详情重取"), "漫画详情重取");
        selected = yuluSelectComicSource(data);
        detailUrl = retryUrl;
    }
    normalized = yuluNormalizeBook(data, domain, 3, detailUrl);
    normalized.toc_url = yuluBuildUrl(api, yuluServiceUrl("c-catalog", domain, selected.list_path), {
        yulu_source_id: selected.source_id
    });
    return normalized;
}

// 解密漫画目录并把章节路径转换为带更新时间的图片列表地址。
function yuluComicChapters(api, body, tocUrl) {
    var data = yuluDecodeEnvelopeBody(api, body, "漫画目录");
    var domain = yuluRootDomain(tocUrl);
    var output = [];
    var index;
    var item;
    var updated;
    if (!yuluIsListLike(data)) {
        throw new Error("漫画目录数据不是数组");
    }
    for (index = 0; index < data.length; index += 1) {
        item = data[index] || {};
        updated = yuluFirstValue(item, ["updated_at", "time"], "");
        output.push({
            title: String(yuluFirstValue(item, ["name", "title"], "")),
            url: yuluBuildUrl(api, yuluServiceUrl("c-pic", domain, yuluFirstValue(item, ["path", "url"], "")), {
                time: updated
            }),
            updated_at: updated
        });
    }
    return output;
}

// 解密漫画图片列表并生成携带解扰参数的连续 img 标签。
function yuluComicContent(api, body, chapterUrl) {
    var data = yuluDecodeEnvelopeBody(api, body, "漫画正文");
    var domain = yuluRootDomain(chapterUrl);
    var output = "";
    var index;
    var item;
    var imageUrl;
    if (!yuluIsListLike(data)) {
        throw new Error("漫画正文数据不是数组");
    }
    for (index = 0; index < data.length; index += 1) {
        item = data[index] || {};
        imageUrl = yuluBuildUrl(api, yuluServiceUrl("c-chapter", domain, yuluFirstValue(item, ["path", "url"], "")), {
            yulu_id: yuluFirstValue(item, ["id", "image_id"], ""),
            yulu_et: yuluFirstValue(item, ["encrypt_type", "encryptType"], 0),
            yulu_ei: yuluFirstValue(item, ["encrypt_info", "encryptInfo"], 0)
        });
        output += "<img src=\"" + imageUrl + "\">";
    }
    return output;
}

// 计算图片 id 文本的标准 CRC32 无符号值。
function yuluCrc32(value) {
    var crc = -1;
    var text = String(value);
    var index;
    var bit;
    crc = crc ^ 0;
    for (index = 0; index < text.length; index += 1) {
        crc = crc ^ (text.charCodeAt(index) & 255);
        for (bit = 0; bit < 8; bit += 1) {
            if ((crc & 1) !== 0) {
                crc = (crc >>> 1) ^ 3988292384;
            } else {
                crc = crc >>> 1;
            }
        }
    }
    return (crc ^ -1) >>> 0;
}

// 按 CRC32 标记删除服务端插入的干扰字节。
function yuluRemoveInsertedBytes(bytes, marker, count) {
    var output = [];
    var index;
    var removed = 0;
    for (index = 0; index < bytes.length; index += 1) {
        output.push(yuluUnsignedByte(bytes[index]));
        if (removed < count && yuluUnsignedByte(bytes[index]) === marker && index + 1 < bytes.length) {
            index += 1;
            removed += 1;
        }
    }
    return output;
}

// 对前四百字节保留偶数位，并拼回未参与解扰的剩余数据。
function yuluCollapseComicPrefix(bytes) {
    var output = [];
    var prefixLength = bytes.length < 400 ? bytes.length : 400;
    var index;
    for (index = 0; index < prefixLength; index += 2) {
        output.push(yuluUnsignedByte(bytes[index]));
    }
    for (index = 400; index < bytes.length; index += 1) {
        output.push(yuluUnsignedByte(bytes[index]));
    }
    return output;
}

// 读取 ByteArray 或 InputStream，并按 URL 参数执行漫画图片两阶段解扰。
function yuluDecodeComicImage(api, input, imageUrl) {
    var encryptType = Number(yuluQueryValue(imageUrl, "yulu_et") || 0);
    var encryptInfoText = yuluQueryValue(imageUrl, "yulu_ei");
    var encryptInfo = Number(encryptInfoText);
    var imageId = yuluQueryValue(imageUrl, "yulu_id");
    var bytes;
    var marker;
    var filtered;
    var collapsed;
    bytes = yuluReadAllBytes(api, input);
    if (encryptType === 0) {
        return bytes;
    }
    if (encryptType !== 1) {
        throw new Error("不支持的漫画图片加密类型：" + String(encryptType));
    }
    if (!/^\d+$/.test(imageId) || !isFinite(Number(imageId))) {
        throw new Error("漫画图片 imageId 必须是非负整数");
    }
    if (!/^\d+$/.test(encryptInfoText) || !isFinite(encryptInfo) ||
            encryptInfo < 0 || Math.floor(encryptInfo) !== encryptInfo) {
        throw new Error("漫画图片 encrypt_info 必须是非负整数");
    }
    marker = yuluCrc32(imageId) & 255;
    filtered = yuluRemoveInsertedBytes(bytes, marker, encryptInfo);
    if (filtered.length < 400) {
        throw new Error("图片解扰后数据长度不足 400 字节");
    }
    collapsed = yuluCollapseComicPrefix(filtered);
    return yuluBytesFromArray(collapsed);
}

