// 获取源变量
function getVariable(k) {
    if (k == undefined) k = "";
    const { source } = this;
    let parsed = {}
    try {
        parsed = JSON.parse(source.getVariable());
    } catch {}
    if (k == "") {
        return parsed;
    }
    let value = parsed[k];
    if (value == undefined) {
        value = defaultConfig[k];
    }
    return value != undefined ? value : "";
}

