        <div class="setting-title">字体颜色</div>
        <div class="setting-desc">设置段评字体颜色</div>
      </div>
      <div class="color-picker-wrapper">
        <input type="color" id="fontColor" value="#A7A7A7" class="color-input">
        <input type="text" id="fontColorText" value="#A7A7A7" class="color-text-input">
      </div>
    </div>

    <div class="setting-item">
      <div class="setting-info">
        <div class="setting-title">填充颜色</div>
        <div class="setting-desc">设置段评背景填充颜色</div>
      </div>
      <div class="color-picker-wrapper">
        <input type="color" id="fillColor" value="#FFFFFF" class="color-input">
        <input type="text" id="fillColorText" value="transparent" class="color-text-input">
        <button id="fillColorTransparent" class="transparent-btn">透明</button>
      </div>
    </div>

    <!-- 自定义样式管理 -->
    <div class="custom-style-section">
      <div class="setting-item" style="flex-direction: column; align-items: flex-start; gap: 12px;">
        <div class="setting-info">
          <div class="setting-title">自定义样式管理</div>
          <div class="setting-desc">点击下方"+"添加新的自定义样式，支持自定义名称</div>
        </div>
        <div style="display: flex; gap: 10px; align-items: center; width: 100%; justify-content: flex-end;">
          <button id="moreStylesBtn" class="more-styles-btn">
            <i class="fas fa-external-link-alt"></i>
            <span class="btn-text">更多样式</span>
          </button>
          <button id="saveCustomStyleBtn" class="save-style-btn">
            <i class="fas fa-save"></i>
            <span class="btn-text">保存自定义</span>
          </button>
          <button id="addCustomStyleBtn" class="add-style-btn">
            <i class="fas fa-plus"></i>
          </button>
        </div>
      </div>

      <div id="customStylesContainer" class="custom-styles-container">
      </div>
