    book.intro = jj;
    result = {
        tur: tur
    };

} else {
    //搜索跳详情重定向处理
    let ii = String(book.bookUrl).startsWith('http');
    if (ii) {
        bkid = String(book.bookUrl).match(/\d{5,}(?=\/?$)/);
        java.put('bkid', bkid);
        book.bookUrl = `data:page;base64,${java.base64Encode('https://m.qidian.com/book/'+bkid)},{"type":"lyc"}`;
    }

    let sinfo = source.getLoginInfoMap();
    bkid = java.get('bkid');
    let rr = cache.getFromMemory('zs' + bkid);
    let rr2 = cache.get('zss' + bkid);
    let rr3 = cache.get('zst' + bkid);
    let url1 = QDSign("v3/bookdetail/get", ["bookId=" + bkid, "isOutBook=0"]);
    let url2 = gethd(qdturl + '/info/' + bkid);
    let url3 = gethd(`https://pre-api.tuishujun.com/api/searchBook?search_value=${book.name}&page=1&pageSize=3`);

    if (!String(rr).startsWith("{")) {
        rr = java.ajax(url1);
        cache.put('zs' + bkid, rr, 86400);
    }
    if (!String(rr2).trim().startsWith("<")) {
        rr2 = java.ajax(url2,9000);
        rr3 ? cache.put('zss' + bkid, rr2, 86400) :
            cache.put('zss' + bkid, rr2, 86400 * 2);
    }
    if (!String(rr3).startsWith("{")) {
        rr3 = java.ajax(url3,9000);
        rr3.includes(`"data":[]`) ?
            cache.put('zst' + bkid, rr3, 864000) :
            cache.put('zst' + bkid, rr3, 864000 * 2);
    }

    //获取起点图作者
    let au = gets('class.media-body@tr.1@a.-1@text', rr2);
    //获取推书君
    let aly = new JavaImporter(Packages.com.jayway.jsonpath);
    with(aly) {
        var jsonp = JsonPath.using(
            Configuration.builder()
            .options(Option.SUPPRESS_EXCEPTIONS)
            .build()
