					.replace(zz, '')
					.replace(/[，。？！…～·、；\.…\-\s]+$/, '') || '洛娅橙橙lyc';
				n1 = (n1 - 40 < 0) ? 0 : (n1 - 10 - cdwqj);
				n2 = n2 + 10;
				tsms && java.log('匹配3\n' + cpx + '♦' + cnm + '\nn1：' + n1 + '，n2：' + n2 + '\n' + zz + '\n请假条' + cdwqj);
				pji = pjr.select(`a:gt(${n1}):lt(${n2}):matchesWholeText(${cnm})`).attr('href');
			}
			if (pji == '') {
				//错误率增高
				let cnm1 = (cnm || '标题为空依靠四位序号的情况').match(/[一-ꀀ]+/g);
				//构建正则
				let zz = /\d{4,}|[零一二三四五六七八九十百千万]{4,}/.test(cpx) ? (cpx + '|') : ''; //序号
				if (cnm.length > 3) {
					for (char of cnm1) zz = zz + char + '.*';
