				pji = pjr.select(`a:gt(${n1}):lt(${n2}):matchesWholeText(${zz})`).attr('href');
				tsms && java.log('解锁目录：\n' + pjr);
			}
			if (pji == '' && cnm) {
				n1 = (n1 > 999) ? (n1 - 10) : n1;
				//去除感叹词，干扰。极大放宽上限
				n2 = n2 + 80;
				cnm = cnm.replace(/吧$/, '');
				let zz = /[3456789]\d{2,}/.test(cpx) ? (cpx + '|') : '';
				zz = zz + cnm;
				tsms && java.log('匹配5\n' + cpx + '♦' + cnm + '\nn1：' + n1 + '，n2：' + n2 + '\n' + zz);
				pji = pjr.select(`a:gt(${n1}):lt(${n2}):matchesWholeText(${zz})`).attr('href');
			}

			if (pji == '') {
				//获取单章替换内容
				pjt = (book.getVariable("avip" + zcid) + '') || 'lyc';
				book.putVariable("nurl" + zcid, nextChapterUrl);
                java.put("nocontent",1);
