			} else {
				//成功
				pji = /^https?:/.test(pji) ? pji : pji.startsWith('//') ? ('https:' + pji) : (cdx + pji);
				tsms && java.log(pji);
				Packages.java.lang.Thread.sleep(Math.random() * 199 | 0);
