let se = false;
try {
    if (ui.startsWith("[")) {
        se = true;
    }
} catch (e) {
    r = eval(java.readTxtFile(java.md5Encode16(lycurl) + '.json') + '' || [''])[0];
    r && cache.putMemory(lycnm, r);
}
if (se) {
    ui
} else {
    java.downloadFile(lycurl);
